import json
from pathlib import Path
from jinja2 import Environment, select_autoescape
from .loader import read_jsonl, write_json, file_hash

TEMPLATE = """<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>开票轨迹评测 · 证据时间线</title>
<style>
:root{color-scheme:light;--ink:#172738;--muted:#526879;--border:#dce4eb;--brand:#146756;--bad:#ac3131}*{box-sizing:border-box}body{margin:0;background:#f3f6f8;color:var(--ink);font:15px/1.65 system-ui,'Microsoft YaHei',sans-serif}header{padding:24px 4vw;background:#102b3d;color:white}header p{margin:4px 0;color:#c6d9e5}h1{font-size:24px;margin:0}main{max-width:1550px;margin:auto;padding:24px}label{display:block;font-weight:600}input,select,button{font:inherit;padding:8px 12px;border:1px solid var(--border);border-radius:6px;background:white;color:var(--ink)}button,a{cursor:pointer}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #1f8bca;outline-offset:2px}.controls{display:flex;gap:16px;flex-wrap:wrap;align-items:end;margin-bottom:20px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.card{background:white;border:1px solid var(--border);border-radius:10px;padding:18px;margin-bottom:16px}.stat{font-size:26px;font-weight:700}.muted{color:var(--muted)}.panels{display:grid;grid-template-columns:1fr 1fr;gap:18px}.events{display:flex;gap:7px;overflow:auto;padding:8px 0 16px}button.event{min-width:68px}.fault{border-color:var(--bad);color:var(--bad)}.active{background:var(--brand);color:white}.tag{font-size:12px;border-radius:4px;padding:3px 7px;background:#edf3f6}pre{overflow:auto;max-height:430px;white-space:pre-wrap;overflow-wrap:anywhere;background:#f5f7f9;padding:12px;border-radius:6px;font:13px/1.6 Consolas,monospace}h2{font-size:19px;margin:0 0 12px}h3{font-size:16px;margin:16px 0 8px}a{color:#126a9a;text-decoration:underline}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:10px;border-bottom:1px solid var(--border)}details{margin-top:12px}summary{cursor:pointer;font-weight:600}.empty{padding:20px;color:var(--muted)}#status{min-height:24px}.root{border-left:3px solid var(--bad);padding-left:12px;margin:12px 0}@media(max-width:900px){.panels{grid-template-columns:1fr}.stats{grid-template-columns:1fr 1fr}main{padding:14px}}
.card{min-width:0;overflow-wrap:anywhere}.controls label{max-width:100%}.controls input,.controls select{max-width:100%}.stats{grid-template-columns:repeat(4,minmax(0,1fr))}.panels{grid-template-columns:repeat(2,minmax(0,1fr))}@media(max-width:900px){.panels{grid-template-columns:minmax(0,1fr)}.stats{grid-template-columns:repeat(2,minmax(0,1fr))}}
</style></head><body><header><h1>开票轨迹评测 · 证据时间线</h1><p>逐事件查看目标、实际状态、首错与后续传播</p></header><main>
<div class="stats"><div class="card">有效覆盖<div class="stat">{{ metrics.valid_runs }} / {{ metrics.input_runs }}</div></div><div class="card">处理正确<div class="stat">{{ metrics.agent_correct.numerator }} / {{ metrics.agent_correct.denominator }}</div></div><div class="card">轨迹记录出票<div class="stat">{{ metrics.service_created.numerator }} / {{ metrics.service_created.denominator }}</div></div><div class="card">版本建议<div class="stat">{{ recommendation }}</div></div></div>
{% if coverage %}<section class="card"><h2>业务行为覆盖</h2><p>清单 {{ coverage.catalog_version }} · 合并覆盖 {{ coverage.overall.coverage.numerator }} / {{ coverage.overall.coverage.denominator }} 项。失败也计入覆盖；计划标签不能代替实际触发。</p><details><summary>查看基线与候选的覆盖缺口</summary><div style="overflow-x:auto"><table><thead><tr><th>行为</th><th>基线</th><th>候选</th></tr></thead><tbody>{% for b in coverage.overall.behaviors %}<tr><td>{{ b.name }}</td><td>{{ behavior_labels[coverage.by_role.baseline.behaviors[loop.index0].status] }}</td><td>{{ behavior_labels[coverage.by_role.candidate.behaviors[loop.index0].status] }}</td></tr>{% endfor %}</tbody></table></div></details></section>{% endif %}
<section class="card" id="business-boundary"><h2>出票证据与外部核验</h2><p>出票结论来自离线输入摘要和回调记录。本评测器未独立查询开票服务或账本；工具受理、Agent 自述和人工判定复核都不能替代外部业务核验。</p>{% if business %}<p>全部 {{ business.summary.input_runs }} 条轨迹：记录出票 {{ business.summary.trace_created }}，记录未出票 {{ business.summary.trace_not_created }}，缺失或冲突 {{ business.summary.trace_unknown }}。独立外部核验 0 / {{ business.summary.input_runs }}；外部真实出票数未知。顶部出票分母仅含有效判定。</p>{% else %}<p>历史产物未保存逐条出票来源说明，不能据此认定外部业务状态已核验。</p>{% endif %}</section>
<div class="controls"><label>查找任务<input id="search" placeholder="输入编号或请求内容"></label><label>选择任务<select id="case"></select></label><label>显示<select id="filter"><option value="all">全部运行</option><option value="bad">存在问题的任务</option><option value="risk">存在严重风险</option></select></label><button id="reset">重置筛选</button></div><div id="status" role="status" aria-live="polite"></div>
<section class="card" id="summary"></section><div class="panels" id="panels"></div>
<section class="card" id="behaviors"></section>
<section class="card"><h2>双模型复核</h2><div id="judges"></div></section>
<section class="card"><h2>如何阅读结果</h2><p>处理正确与轨迹记录出票分别判断，质量分依据配置规则计算。点击根因或红色事件查看对应证据。缺少关键证据的运行需要人工复核，版本建议仅反映本次输入和配置。</p></section>
</main><script id="data" type="application/json">{{ data|safe }}</script><script>
'use strict';const data=JSON.parse(document.querySelector('#data').textContent);const $=s=>document.querySelector(s);const escape=s=>String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]));let selected=null;
function assessment(id){return data.individual.find(a=>a.run_id===id)}
function options(){const term=$('#search').value.toLowerCase(),filter=$('#filter').value;const cs=data.cases.filter(c=>JSON.stringify([c.case_id,c.user_request]).toLowerCase().includes(term)).filter(c=>filter==='all'||c.runs.some(r=>{const a=assessment(r.run_id);return a&&(filter==='bad'?!a.agent_task_success:a.penalty_items.some(p=>p.dimension==='RISK_CONTROL'))}));$('#case').innerHTML=cs.map(c=>'<option value="'+escape(c.case_id)+'">'+escape(c.case_id)+'</option>').join('');if(cs.some(c=>c.case_id===selected))$('#case').value=selected;$('#status').textContent='筛选得到 '+cs.length+' 个任务';render()}
function renderCase(){selected=$('#case').value;const c=data.cases.find(c=>c.case_id===selected);if(!c){$('#summary').textContent='没有匹配的任务';$('#panels').innerHTML='';$('#judges').textContent='';return}const record=data.records.find(r=>r.case_id===selected);$('#summary').innerHTML='<h2>'+escape(c.case_id)+'</h2><p>'+escape(c.user_request)+'</p><p class="muted">'+escape(record?record.version_comparison.reason:'存在待复核判断，未发布本 Case 评价')+'</p>';$('#panels').innerHTML=c.runs.map((r,i)=>{const a=assessment(r.run_id);return '<section class="card" id="run'+i+'"><h2>'+escape(r.agent_version)+' · '+escape(r.run_id)+'</h2>'+(a?'<p>质量分 <b>'+a.quality_score+'</b> · 处理正确 '+(a.agent_task_success?'是':'否')+' · 轨迹记录出票 '+(a.business_invoice_created?'是':'否')+'</p>':'<p>待复核</p>')+'<div class="roots">'+(a?a.root_causes.map(root=>'<div class="root"><b>'+escape(root.label)+'</b><br>'+escape(root.explanation)+'<br><a '+(root.first_fault_event_id?'href="#" data-run="'+i+'" data-event="'+escape(root.first_fault_event_id??'未定位')+'"':'')+'>首错 '+escape(root.first_fault_event_id??'未定位')+'</a><p class="muted">证据 '+root.evidence_event_ids.map(escape).join(' → ')+'</p></div>').join(''):'')+'</div><div class="events">'+[...r.events].sort((a,b)=>a.seq-b.seq).map(e=>'<button class="event '+(a&&a.root_causes.some(x=>x.first_fault_event_id===e.event_id)?'fault':'')+'" data-run="'+i+'" data-event="'+escape(e.event_id)+'" title="'+escape(e.step_id)+'">'+e.seq+'</button>').join('')+'</div><div class="detail"></div></section>'}).join('');c.runs.forEach((r,i)=>showEvent(i,[...r.events].sort((a,b)=>a.seq-b.seq)[0].event_id));renderJudges(c)}
function showEvent(i,id){const c=data.cases.find(c=>c.case_id===selected),r=c.runs[i],e=r.events.find(e=>e.event_id===id);if(!e)return;const state=data.states.find(s=>s.run_id===r.run_id)?.snapshots.find(s=>s.event_id===id);document.querySelectorAll('#run'+i+' button.event').forEach(b=>b.classList.toggle('active',b.dataset.event===id));$('#run'+i+' .detail').innerHTML='<h3>'+escape(e.seq+' · '+e.step_id)+'</h3><p><span class="tag">'+escape(e.step_status)+'</span> '+escape(e.event_id)+'</p><details><summary>原始事件</summary><pre>'+escape(JSON.stringify(e,null,2))+'</pre></details><details><summary>当时目标、实际字段及确认来源</summary><pre>'+escape(JSON.stringify(state,null,2))+'</pre></details>'}
function renderJudges(c){const rows=(data.audit?.comparisons||[]).filter(x=>x.case_id===c.case_id);$('#judges').innerHTML=rows.length?rows.map(x=>'<details><summary>'+escape(x.run_id)+' · '+escape(x.status)+'</summary><pre>'+escape(JSON.stringify(x,null,2))+'</pre></details>').join(''):'<p class="muted">本报告未附双模型复核结果。</p>'}
function renderBehaviors(){const section=$('#behaviors'),c=data.cases.find(c=>c.case_id===$('#case').value);const rows=(data.behavior_coverage?.observations||[]).filter(r=>c&&r.case_id===c.case_id&&(r.planned||r.triggered));section.hidden=!rows.length;const labels={pass:'通过',fail:'失败',unknown:'证据不足',not_covered:'未覆盖'};section.innerHTML='<h2>当前任务的行为与证据</h2>'+rows.map(r=>{const index=c.runs.findIndex(x=>x.run_id===r.run_id),definition=data.behavior_coverage.overall.behaviors.find(b=>b.id===r.behavior_id);return '<details><summary>'+escape((r.role==='baseline'?'基线':'候选')+' · '+definition.name+' · '+labels[r.status])+'</summary><p>计划覆盖：'+(r.planned?'是':'否')+'；实际触发：'+(r.triggered?'是':'否')+'；实际覆盖：'+(r.covered?'是':'否')+'</p>'+r.occurrences.map(o=>'<p>'+escape(o.reason)+'<br>触发来源：'+escape(o.trigger_field_paths.join(', '))+'<br>事件：'+o.evidence_event_ids.map(id=>'<a href="#" data-run="'+index+'" data-event="'+escape(id)+'">'+escape(id)+'</a>').join(' → ')+'</p>').join('')+'</details>'}).join('')}
document.addEventListener('click',e=>{const t=e.target.closest('[data-event]');if(t){e.preventDefault();showEvent(Number(t.dataset.run),t.dataset.event)}});$('#search').addEventListener('input',options);$('#filter').addEventListener('change',options);$('#case').addEventListener('change',render);$('#reset').addEventListener('click',()=>{$('#search').value='';$('#filter').value='all';options()});options();
function renderBusinessEvidence(){const c=data.cases.find(c=>c.case_id===selected);if(!c)return;const labels={consistent:'记录一致',missing:'记录缺失',conflicting:'记录冲突'},kinds={run_summary:'输入运行摘要',callback_output:'轨迹回调字段',callback_tool_result:'轨迹回调工具结果'};c.runs.forEach((r,i)=>{const row=data.business_evidence?.runs.find(x=>x.run_id===r.run_id)||assessment(r.run_id)?.business_invoice_evidence;let content='<p>未保存逐条出票来源；外部业务状态未核验。</p>';if(row){const created=row.invoice_created===null?'未知':row.invoice_created?'是':'否';content='<p>轨迹记录出票：'+created+' · '+escape(labels[row.status]||row.status)+'；独立外部核验：未执行。</p><p class="muted">记录一致不证明记录真实或来源独立。</p>'+row.sources.map(s=>'<p>'+escape(kinds[s.kind]||s.kind)+' · '+escape(s.source_path)+'<br>记录值：'+escape(JSON.stringify(s.recorded_value))+' · '+(s.event_id?'<a href="#" data-run="'+i+'" data-event="'+escape(s.event_id)+'">'+escape(s.event_id)+'</a>':'无事件编号（运行摘要）')+'</p>').join('')+row.non_decisive_signals.map(s=>'<p class="muted">未用于出票判定：'+escape(s.source_path)+' = '+escape(JSON.stringify(s.recorded_value))+'；'+escape(s.reason)+'</p>').join('')}$('#run'+i+' .roots').insertAdjacentHTML('beforebegin','<details class="business-evidence"><summary>出票来源与核验边界</summary>'+content+'</details>')})}
function render(){renderCase();renderBusinessEvidence();renderBehaviors()}
</script></body></html>"""

def render_timeline(directory, output, audit=None):
    directory, output = Path(directory), Path(output)
    def read(name):
        return json.loads((directory/name).read_text(encoding="utf-8"))
    def rows(name):
        return read_jsonl(directory/name) if (directory/name).stat().st_size else []
    data = {"cases": rows("cases.snapshot.jsonl"), "records": rows("assessments.jsonl"), "individual": [row["assessment"] for row in rows("run_assessments.jsonl")], "states": rows("states.jsonl"), "metrics": read("metrics.json"), "manifest": read("manifest.json"), "audit": json.loads(Path(audit).read_text(encoding="utf-8")) if audit else None}
    data["behavior_coverage"] = read("behavior_coverage.json") if (directory/"behavior_coverage.json").exists() else None
    data["business_evidence"] = read("business_evidence.json") if (directory/"business_evidence.json").exists() else None
    encoded = json.dumps(data, ensure_ascii=False).replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")
    env = Environment(autoescape=select_autoescape(default=True))
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(env.from_string(TEMPLATE).render(data=encoded, metrics=data["metrics"], business=data["business_evidence"], coverage=data["behavior_coverage"], behavior_labels={"pass":"通过", "fail":"失败", "unknown":"证据不足", "not_covered":"未覆盖"}, recommendation={"release":"满足配置门槛", "defer":"暂缓", "gray":"待复核", "investigate":"需核查"}.get(data["metrics"]["release_recommendation"], "需核查")), encoding="utf-8")
    return output
